        print_version();
        return EC_OK;
    }

    struct PassportResult result = read_passport(stdin);
    if (result.error != PE_OK) {
        char msg[PASSPORT_ERROR_TEXT_SIZE];
        passport_error_message(&result, msg, sizeof msg);
        fprintf(stderr, "%s\n", msg);
        switch (result.error) {
        case PE_NO_INPUT:
            return EC_NOINPUT;
        case PE_EMPTY_NAME:
        case PE_BAD_COUNT:
        case PE_NEGATIVE_COUNT:
            return EC_DATA;
        case PE_IO_ERROR:
            return EC_IOERR;
        default:
            return 1;
        }
    }

    printf("Изображение \xAB%s\xBB: %d %s.\n", result.name, result.count, pixel_word(result.count));
    free(result.name);
    return EC_OK;
}

