static void check_pixel(const struct Pixel* p, int er, int eg, int eb, const char* name) {
    if (p->r != er || p->g != eg || p->b != eb) {
        fprintf(stderr, "FAIL: %s -- got (%d,%d,%d) expected (%d,%d,%d)\n", name, p->r, p->g, p->b,
                er, eg, eb);
        ++failed;
    } else {
        printf("PASS: %s\n", name);
    }
}

static FILE* make_ppm(const char* data) {
    FILE* f = tmpfile();
    if (!f) {
        fprintf(stderr, "FAIL: tmpfile creation failed\n");
        return NULL;
    }
    fputs(data, f);
    rewind(f);
    return f;
}

static void check_text(const struct PpmResult* r, const char* expected, const char* name) {
    if (strcmp(r->diagnostic, expected) != 0) {
        fprintf(stderr, "FAIL: %s -- got \"%s\" expected \"%s\"\n", name, r->diagnostic, expected);
        ++failed;
    } else {
        printf("PASS: %s\n", name);
    }
}

