enum { MAGIC_ECHO_MAX = 127 };
enum { MAGIC_SHOWN_MAX = 384 };

// Разделители полей PPM: blanks, TABs, CRs, LFs; '#' начинает комментарий.
static int is_field_sep(int c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '#';
}

// Печатаемые ASCII - как есть, остальные байты - \xNN. Потолок MAGIC_SHOWN_MAX
// байт, чтобы диагностика уложилась в PPM_DIAG_SIZE вместе с префиксом.
static void render_token(const char* token, size_t len, char* out, size_t out_sz) {
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char ch = (unsigned char)token[i];
        size_t need = (ch >= 0x20 && ch <= 0x7E) ? 1 : 4;
        if (n + need >= out_sz)
            break;
        if (need == 1) {
            out[n++] = (char)ch;
        } else {
            int w = snprintf(out + n, out_sz - n, "\\x%02x", ch);
            if (w < 0)
                break;
            n += (size_t)w;
        }
    }
    out[n] = '\0';
}
