if (!skip_ws())
    return err(PpmReadError::kEmptyInput, line_num, "нет входных данных");

std::string magic;
std::size_t magic_len = 0;
for (;;) {
    int c = is.peek();
    if (c == EOF || is_field_sep(c))
        break;
    is.get();
    ++magic_len;
    if (magic.size() < kMagicEchoMax)
        magic.push_back(static_cast<char>(c));
}
if (is.bad())
    return io_error();

