void test_magic_strict() {
    const std::array<std::pair<std::string_view, std::string_view>, 5> bad{{
        {"P31\n1 1\n255\n0 0 0\n", "строка 1: ожидалось 'P3', получено: 'P31'"},
        {"P3x\n1 1\n255\n0 0 0\n", "строка 1: ожидалось 'P3', получено: 'P3x'"},
        {"X3\n1 1\n255\n0 0 0\n", "строка 1: ожидалось 'P3', получено: 'X3'"},
        {"P 3\n1 1\n255\n0 0 0\n", "строка 1: ожидалось 'P3', получено: 'P'"},
        {"P\x01\n1 1\n255\n0 0 0\n", "строка 1: ожидалось 'P3', получено: 'P\\x01'"},
    }};
    for (const auto& [data, expected] : bad) {
        auto ss = std::istringstream(std::string{data});
        auto r = Image::read(ss);
        check(!r.value.has_value(), data);
        if (!r.value.has_value()) {
            check(r.value.error() == PpmReadError::kBadMagic, data);
            check_diag(r, expected, data);
        }
    }

    const std::array<std::string_view, 5> valid{{
        "P3\n1 1\n255\n0 0 0\n",
        "P3\r\n1 1\n255\n0 0 0\n",
        "P3\t1 1\n255\n0 0 0\n",
        "P3 1 1\n255\n0 0 0\n",
        "P3#comment\n1 1\n255\n0 0 0\n",
    }};
    for (auto data : valid) {
        auto ss = std::istringstream(std::string{data});
        auto r = Image::read(ss);
        check(r.value.has_value(), data);
    }

    auto ss = std::istringstream("P3");
    auto r = Image::read(ss);
    check(!r.value.has_value(), "P3 then EOF -> error");
    if (!r.value.has_value()) {
        check(r.value.error() == PpmReadError::kBadNumber, "P3 then EOF -> kBadNumber");
        check_diag(r, "строка 1: неожиданный конец файла", "P3 then EOF -> diagnostic");
    }
}

