static inline enum KvIntParse kv_parse_u32(const char* s, uint32_t* out) {
    if (!s || !*s)
        return KV_INT_INVALID;
    const char* p = s;
    for (; *p; ++p)
        if (*p < '0' || *p > '9')
            return KV_INT_INVALID;
    uint64_t value = 0;
    for (p = s; *p; ++p) {
        uint64_t digit = (uint64_t)(*p - '0');
        if (value > (UINT32_MAX - digit) / 10)
            return KV_INT_RANGE;
        value = value * 10 + digit;
    }
    *out = (uint32_t)value;
    return KV_INT_OK;
}
```
Can do in one pass: validate digit then accumulate with check. Let me merge:

```c
