        int64_t digit = *p - '0';
        if (value > (limit - digit) / 10)
            return KV_INT_RANGE;
        value = value * 10 + digit;
    }
    if (*p == '\0' && p == s + negative)
        return KV_INT_INVALID;

    *out = (int32_t)(negative ? -value : value);
    return KV_INT_OK;
}

